<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { IonApp, IonButton, IonCard, IonCardContent, IonContent, IonHeader, IonInput, IonItem, IonLabel, IonList, IonNote, IonTitle, IonToolbar } from '@ionic/vue'
import { createPlayer, nextPlayer, playCard, playerName, startMatch } from './game'
import { isNativeBluetooth, joinRoom, listen, message, searchRooms, send, startHost, stopBluetooth } from './bluetooth'
import { clearHistory, deleteHistory, getHistory, saveHistory } from './storage'
import type { HistoryItem, Match, Player } from './types'

type Screen = 'inicio' | 'identificacao' | 'conexao' | 'sala' | 'jogo' | 'resultado' | 'historico' | 'detalhes'
type Role = 'demo' | 'host' | 'client'
const screen = ref<Screen>('inicio'), name = ref(''), error = ref(''), notice = ref(''), busy = ref(false), role = ref<Role>('demo')
const me = ref<Player | null>(null), room = ref<Player[]>([]), match = ref<Match | null>(null), selected = ref('')
const history = ref<HistoryItem[]>([]), detail = ref<HistoryItem | null>(null), foundRooms = ref<{ deviceId: string; name: string }[]>([])
const pending = ref<{ id: string; name: string; deviceId: string }[]>([])
const local = computed(() => match.value?.players.find(p => p.id === me.value?.id))
const isMyTurn = computed(() => match.value?.turnPlayerId === me.value?.id)
const destination = computed(() => match.value && me.value ? nextPlayer(match.value, me.value.id).name : '')
const symbol: Record<string, string> = { copas: '♥', ouros: '♦', paus: '♣', espadas: '♠' }

function go(to: Screen) { error.value = ''; notice.value = ''; screen.value = to }
function back() { const route: Partial<Record<Screen, Screen>> = { identificacao: 'inicio', conexao: 'identificacao', sala: 'conexao', jogo: 'sala', resultado: 'inicio', historico: 'inicio', detalhes: 'historico' }; if (route[screen.value]) go(route[screen.value]!) }
function identify() { if (name.value.trim().length < 2) return error.value = 'Informe um nome com ao menos 2 caracteres.'; me.value = createPlayer(name.value); go('conexao') }
function publicPlayers(players: Player[]) { return players.map(({ id, name, isHost, connected, burro }) => ({ id, name, isHost, connected, burro, hand: [] as never[] })) }
function privateMatch(game: Match, playerId: string): Match { return { ...game, players: game.players.map(p => ({ ...p, deviceId: undefined, hand: p.id === playerId ? p.hand : [] })) } }
async function broadcastRoom() { if (!me.value) return; await send(message('JOGADOR_ENTROU', 'sala', me.value.id, { players: publicPlayers(room.value) })) }
async function createBluetoothRoom() { if (!me.value) return; busy.value = true; try { await startHost(); role.value = 'host'; me.value.isHost = true; room.value = [me.value]; notice.value = 'Sala anunciada. Aguarde pedidos de entrada.'; go('sala') } catch (e) { error.value = e instanceof Error ? e.message : 'Falha ao criar sala Bluetooth.' } finally { busy.value = false } }
async function findBluetoothRooms() { busy.value = true; foundRooms.value = []; try { await searchRooms(device => { if (!foundRooms.value.some(x => x.deviceId === device.deviceId)) foundRooms.value.push(device) }); notice.value = 'Procurando salas próximas...'; } catch (e) { error.value = e instanceof Error ? e.message : 'Falha ao procurar salas.' } finally { busy.value = false } }
async function enterBluetoothRoom(deviceId: string) { role.value = 'client'; busy.value = true; try { await joinRoom(deviceId); notice.value = 'Conectando ao anfitrião...'; } catch (e) { error.value = e instanceof Error ? e.message : 'Falha ao conectar.' } finally { busy.value = false } }
async function approve(candidate: { id: string; name: string; deviceId: string }) { if (!me.value || room.value.length >= 6) return; room.value.push({ ...createPlayer(candidate.name), id: candidate.id, deviceId: candidate.deviceId }); pending.value = pending.value.filter(p => p.id !== candidate.id); await broadcastRoom() }
function reject(id: string) { pending.value = pending.value.filter(p => p.id !== id) }
function addDemoPlayer() { room.value.push(createPlayer(`Jogador ${room.value.length + 1}`)) }
function removePlayer(id: string) { room.value = room.value.filter(p => p.id !== id) }
async function syncGame() { if (!match.value || !me.value || role.value !== 'host') return; for (const player of room.value.filter(p => p.id !== me.value?.id && p.deviceId)) await send(message('TROCA_REALIZADA', match.value.id, me.value.id, { match: privateMatch(match.value, player.id) }), player.deviceId) }
async function begin() { try { match.value = startMatch(room.value); selected.value = ''; if (role.value === 'host') { await syncGame(); await send(message('PARTIDA_INICIADA', match.value.id, me.value!.id, { players: publicPlayers(match.value.players) })) } go('jogo') } catch (e) { error.value = e instanceof Error ? e.message : 'Erro ao iniciar.' } }
async function applyPlay(playerId: string, cardId: string) { if (!match.value) return; match.value = playCard(match.value, playerId, cardId); selected.value = ''; if (role.value === 'host') await syncGame(); if (match.value.status === 'finalizada') await finish() }
async function confirmCard() { if (!match.value || !me.value || !selected.value) return error.value = 'Selecione uma carta.'; try { if (role.value === 'client') { await send(message('JOGADA', match.value.id, me.value.id, { cardId: selected.value })); selected.value = ''; notice.value = 'Jogada enviada ao anfitrião para validação.' } else await applyPlay(me.value.id, selected.value) } catch (e) { error.value = e instanceof Error ? e.message : 'Jogada inválida.' } }
async function simulateOpponent() { if (!match.value || isMyTurn.value) return; const opponent = match.value.players.find(p => p.id === match.value?.turnPlayerId); if (opponent?.hand[0]) await applyPlay(opponent.id, opponent.hand[0].id) }
async function finish() { if (!match.value || !me.value) return; const item: HistoryItem = { ...match.value, localResult: match.value.winnerId === me.value.id ? 'vitória' : match.value.penalizedId === me.value.id ? 'penalizado' : 'participou' }; await saveHistory(item); detail.value = item; if (role.value === 'host') await send(message('PARTIDA_FINALIZADA', match.value.id, me.value.id, { winnerId: match.value.winnerId, penalizedId: match.value.penalizedId })); go('resultado') }
async function openHistory() { history.value = await getHistory(); go('historico') }
async function erase(id: string) { if (confirm('Excluir esta partida do histórico?')) { await deleteHistory(id); history.value = await getHistory() } }
async function eraseAll() { if (confirm('Limpar todo o histórico?')) { await clearHistory(); history.value = [] } }
async function leave() { await stopBluetooth(); role.value = 'demo'; room.value = []; match.value = null; go('inicio') }

onMounted(() => listen(async (value, deviceId) => {
  if (!me.value) return
  if (value.type === 'SOLICITACAO_ENTRADA' && role.value === 'host') { const p = value.payload as { name?: string; playerId?: string }; if (p.name && p.playerId && !pending.value.some(x => x.id === p.playerId)) pending.value.push({ id: p.playerId, name: p.name, deviceId }) }
  if (value.type === 'JOGADOR_ENTROU' && role.value === 'client') { const players = value.payload.players as Player[] | undefined; if (players) { room.value = players; go('sala') } }
  if (value.type === 'PARTIDA_INICIADA' && role.value === 'client') { notice.value = 'Partida iniciada. Recebendo suas cartas...'; go('jogo') }
  if (value.type === 'TROCA_REALIZADA' && role.value === 'client') { const state = value.payload.match as Match | undefined; if (state) { match.value = state; room.value = state.players; go('jogo') } }
  if (value.type === 'JOGADA' && role.value === 'host' && match.value) { const cardId = value.payload.cardId; if (typeof cardId === 'string') { try { await applyPlay(value.playerId, cardId) } catch { error.value = 'O anfitrião recusou uma jogada inválida.' } } }
  if (value.type === 'PARTIDA_FINALIZADA' && role.value === 'client' && match.value) { match.value = { ...match.value, status: 'finalizada', winnerId: value.payload.winnerId as string, penalizedId: value.payload.penalizedId as string, endedAt: new Date().toISOString() }; await finish() }
}, async (state, deviceId) => { if (state === 'CONECTADO' && role.value === 'client' && me.value) await send(message('SOLICITACAO_ENTRADA', 'sala', me.value.id, { name: me.value.name, playerId: me.value.id })); if (state === 'DESCONECTADO') { notice.value = `Conexão perdida: ${deviceId}.`; if (match.value && match.value.status === 'em_andamento') match.value.status = 'interrompida' } }, value => error.value = value))
</script>

<template><ion-app><ion-header><ion-toolbar color="primary"><ion-button v-if="screen !== 'inicio'" slot="start" fill="clear" color="light" aria-label="Voltar" @click="back">‹</ion-button><ion-title>Jogo do Jegue</ion-title></ion-toolbar></ion-header><ion-content class="ion-padding"><main>
<p v-if="error" class="error">{{ error }}</p><p v-if="notice" class="notice">{{ notice }}</p>
<section v-if="screen === 'inicio'" class="center hero-screen"><div class="donkey">♞</div><span class="eyebrow">BLUETOOTH • MULTIPLAYER</span><h1>Jogo do Jegue</h1><p>Forme quatro cartas do mesmo valor antes dos outros jogadores.</p><ion-button expand="block" @click="go('identificacao')">Jogar agora</ion-button><ion-button fill="outline" expand="block" @click="openHistory">Histórico</ion-button></section>
<section v-else-if="screen === 'identificacao'"><h2>Quem vai jogar?</h2><ion-item><ion-input v-model="name" label="Seu nome" label-placement="stacked" placeholder="Ex.: Gabriel"></ion-input></ion-item><ion-button expand="block" @click="identify">Continuar</ion-button></section>
<section v-else-if="screen === 'conexao'"><h2>Conexão Bluetooth</h2><p v-if="isNativeBluetooth()">Crie uma sala neste celular ou procure um anfitrião próximo.</p><p v-else>Bluetooth real funciona no APK Android. No navegador, use a demonstração.</p><ion-button expand="block" :disabled="busy" @click="createBluetoothRoom">Criar sala Bluetooth</ion-button><ion-button expand="block" fill="outline" :disabled="busy" @click="findBluetoothRooms">Procurar salas Bluetooth</ion-button><ion-list v-if="foundRooms.length"><ion-item v-for="device in foundRooms" :key="device.deviceId"><ion-label>{{ device.name }}</ion-label><ion-button @click="enterBluetoothRoom(device.deviceId)">Entrar</ion-button></ion-item></ion-list><ion-button fill="clear" @click="role = 'demo'; room = me ? [me] : []; go('sala')">Modo demonstração</ion-button></section>
<section v-else-if="screen === 'sala'"><h2>Sala de espera</h2><p><b>Anfitrião:</b> {{ room.find(p => p.isHost)?.name ?? 'aguardando' }} · {{ room.length }}/6 · {{ role === 'demo' ? 'demonstração' : 'Bluetooth conectado' }}</p><ion-list><ion-item v-for="p in room" :key="p.id"><ion-label>{{ p.name }} <ion-note v-if="p.isHost">(anfitrião)</ion-note></ion-label><ion-button v-if="role === 'host' && p.id !== me?.id" fill="clear" color="danger" @click="removePlayer(p.id)">Remover</ion-button></ion-item><ion-item v-for="p in pending" :key="p.id"><ion-label>Pedido: {{ p.name }}</ion-label><ion-button color="success" @click="approve(p)">Aceitar</ion-button><ion-button color="danger" fill="clear" @click="reject(p.id)">Recusar</ion-button></ion-item></ion-list><ion-button v-if="role === 'demo'" fill="outline" :disabled="room.length >= 6" @click="addDemoPlayer">Adicionar jogador demo</ion-button><ion-button v-if="role !== 'client'" expand="block" :disabled="room.length < 2" @click="begin">Iniciar partida</ion-button><p v-else>Aguarde o anfitrião iniciar a partida.</p><ion-button fill="clear" color="medium" @click="leave">Sair da sala</ion-button></section>
<section v-else-if="screen === 'jogo' && match && local"><div class="status"><span>Rodada {{ match.rounds + 1 }}</span><b :class="{ turn: isMyTurn }">{{ isMyTurn ? 'É sua vez!' : `Vez de ${playerName(match, match.turnPlayerId)}` }}</b></div><p>Você envia para <b>{{ destination }}</b>. As cartas dos adversários não são exibidas.</p><h2>Sua mão ({{ local.hand.length }})</h2><div class="cards"><button v-for="card in local.hand" :key="card.id" class="card" :class="[{ selected: selected === card.id }, card.suit]" :disabled="!isMyTurn" @click="selected = card.id"><strong>{{ card.value }}</strong><span>{{ symbol[card.suit] }}</span></button></div><ion-button expand="block" :disabled="!isMyTurn || !selected" @click="confirmCard">Confirmar envio</ion-button><ion-button v-if="role === 'demo' && !isMyTurn" fill="outline" expand="block" @click="simulateOpponent">Simular turno adversário</ion-button></section>
<section v-else-if="screen === 'resultado' && detail" class="center"><h2>Partida finalizada</h2><ion-card><ion-card-content><p>Vencedor: <b>{{ playerName(detail, detail.winnerId) }}</b></p><p>Penalizado: <b>{{ playerName(detail, detail.penalizedId) }}</b></p><p>{{ detail.endReason }} · {{ detail.rounds }} rodadas</p></ion-card-content></ion-card><ion-button expand="block" @click="leave">Nova partida</ion-button><ion-button fill="outline" expand="block" @click="openHistory">Ver histórico</ion-button></section>
<section v-else-if="screen === 'historico'"><h2>Histórico</h2><p v-if="!history.length">Nenhuma partida registrada ainda.</p><ion-list><ion-item v-for="item in history" :key="item.id" button @click="detail = item; go('detalhes')"><ion-label><b>{{ new Date(item.startedAt).toLocaleString('pt-BR') }}</b><p>{{ item.players.length }} jogadores · {{ item.status }} · {{ item.localResult }}</p></ion-label><ion-button fill="clear" color="danger" @click.stop="erase(item.id)">Excluir</ion-button></ion-item></ion-list><ion-button v-if="history.length" color="danger" fill="outline" @click="eraseAll">Limpar histórico</ion-button></section>
<section v-else-if="screen === 'detalhes' && detail"><h2>Detalhes da partida</h2><ion-card><ion-card-content><p>Início: {{ new Date(detail.startedAt).toLocaleString('pt-BR') }}</p><p>Término: {{ detail.endedAt ? new Date(detail.endedAt).toLocaleString('pt-BR') : '—' }}</p><p>Ordem: {{ detail.players.map(p => p.name).join(' → ') }}</p><p>Vencedor: {{ playerName(detail, detail.winnerId) }}</p><p>Penalizado: {{ playerName(detail, detail.penalizedId) }}</p><p>Rodadas: {{ detail.rounds }} · Motivo: {{ detail.endReason ?? detail.status }}</p></ion-card-content></ion-card></section>
</main></ion-content></ion-app></template>
